import React, { useContext, useEffect, useState } from 'react'
import {Link} from "react-router-dom";
import './Reports.css'
import { AuthContext } from './AuthContext';

import axios from "axios";



export default function Reports() {
    const { user, dispatch } = useContext(AuthContext);

    useEffect(() => {
        const fetchUser = async () => {
            try {
                const response = await axios.get('/api/user/' + user._id);
                dispatch({ type: 'LOGIN_SUCCESS', payload: response.data });
            } catch (error) {
                dispatch({ type: 'LOGIN_FAIL', payload: error });
            }
        };

        if (user && !user.role_id) {
            fetchUser();
        }
    }, [user, dispatch]);




    return (
        <>
            <div className="ReportsButton">
                {user === null ? (
                    <div></div>
                ) : (
                    <>
                        {(user.role_id === '3' || user.role_id === '4') && (
                            <Link to='/ReportsHistory' className='linkReports'>Отчет по истории</Link>
                        )}
                        <br/>
                        {(user.role_id === '2' || user.role_id === '3' || user.role_id === '4') && (
                            <Link to='/ReportsNominations' className='linkReports'>Отчет по номинациям</Link>
                        )}
                    </>
                )}
            </div>
        </>
    );
}
